function compressConsecutive(str) {
  let res = '';
  let i = 0;
  while (i < str.length) {
    if (i + 1 < str.length && str[i] === str[i + 1]) {
      res += '#';
      const ch = str[i];
      while (i < str.length && str[i] === ch) {
        i++;
      }
    } else {
      res += str[i];
      i++;
    }
  }
  return res;
}
window.compressConsecutive = compressConsecutive;
const outEl = document.getElementById('output');
if (outEl) outEl.textContent = compressConsecutive('aaaaabcccccd');

